'use strict';
// event-taxonomy.js — the system's events, generated from its event nodes (data/nodes/event/), never hand-written.
// The system events below are the ones the skeleton's own parts emit whether or not a node names them.
const SYSTEM = ['[[slug]].heartbeat', '[[slug]].node.changed', '[[slug]].command.ran', '[[slug]].listener.failed',
  // a handoff's life on the receiving side, and the receipts that come back (lib/handoff.js)
  '[[slug]].handoff.taken', '[[slug]].handoff.done', '[[slug]].handoff.failed', '[[slug]].handoff.reported', '[[slug]].handoff.recovered', '[[slug]].handoff.drain_failed'];

function taxonomy(index) {
  const out = Object.fromEntries(SYSTEM.map(e => [e, { from: 'skeleton' }]));
  for (const e of index.list('event')) out[e.id] = { from: 'node', command: e.command, payload: e.payload };
  return out;
}

function declared(index) { return (event) => SYSTEM.includes(event) || !!index.get('event', event); }

module.exports = { SYSTEM, taxonomy, declared };

'use strict';
// lib/boundary.js — the system holds only its own folder. James, 2026-10-17: "each system is soveriegn and self contained." ·
// "all system relevant files should stay with the system." Every relative require() in this system's own files is resolved;
// one that lands outside the folder is named, and the heartbeat reports it as a problem. Other systems are reached through
// their contract (routes, the CLI, handoffs), never by requiring their files. A module under modules/ is its own system and
// is checked by its own boundary; node_modules and data/ hold no code of the system's.
const fs = require('fs');
const path = require('path');

const SKIP = new Set(['node_modules', 'data', 'modules', 'input', 'processing', 'done', 'failed', 'output']);
const REQ = /(?:\b_?require|\bimport)\s*\(\s*['"](\.{1,2}\/[^'"]+)['"]\s*\)|\bfrom\s+['"](\.{1,2}\/[^'"]+)['"]/g;

// codeOnly(src) — the source with template-literal text and comments blanked (spaces; newlines kept, so every offset is the real
// one). A code generator writes require('../x') into the text it emits; that text is not this file's code (EAS1a, 2026-10-31: found
// laying Emerge out). ${...} inside a template is code and stays. Returns null when a template, comment, string or regex never
// ends; the caller then scans the raw source, so nothing is hidden.
const REGEX_AFTER = new Set(['', '(', ',', '=', ':', '[', '!', '&', '|', '?', '{', '}', ';', '+', '-', '*', '%', '<', '>', '~', '^']);
function codeOnly(src) {
  const out = src.split('');
  const blank = (i) => { if (i < out.length && out[i] !== '\n') out[i] = ' '; };
  const holes = [];          // the brace depth at each ${ we are inside, innermost last
  let depth = 0, prev = '', i = 0;
  const n = src.length;
  const text = () => {       // template text from i: blanked up to the closing backtick or the next ${
    for (;;) {
      if (i >= n) return false;
      if (src[i] === '\\') { blank(i); blank(i + 1); i += 2; continue; }
      if (src[i] === '`') { i++; return true; }
      if (src[i] === '$' && src[i + 1] === '{') { i += 2; holes.push(depth); return true; }
      blank(i++);
    }
  };
  while (i < n) {
    const c = src[i], d = src[i + 1];
    if (c === '/' && d === '/') { while (i < n && src[i] !== '\n') blank(i++); continue; }
    if (c === '/' && d === '*') { const e = src.indexOf('*/', i + 2); if (e < 0) return null; while (i < e + 2) blank(i++); continue; }
    if (c === '/' && (REGEX_AFTER.has(prev) || prev === 'kw')) {
      let cls = false; i++;
      while (i < n && (cls || src[i] !== '/')) {
        if (src[i] === '\n') return null;
        if (src[i] === '\\') i++; else if (src[i] === '[') cls = true; else if (src[i] === ']') cls = false;
        i++;
      }
      if (i >= n) return null;
      i++; prev = 'val'; continue;
    }
    if (c === '"' || c === "'") {
      i++;
      while (i < n && src[i] !== c) { if (src[i] === '\n') return null; if (src[i] === '\\') i++; i++; }
      if (i >= n) return null;
      i++; prev = 'val'; continue;
    }
    if (c === '`') { i++; if (!text()) return null; prev = 'val'; continue; }
    if (c === '}' && holes.length && holes[holes.length - 1] === depth) { holes.pop(); i++; if (!text()) return null; prev = 'val'; continue; }
    if (c === '{') depth++;
    else if (c === '}') depth--;
    if (/[\w$]/.test(c)) {
      let j = i; while (j < n && /[\w$]/.test(src[j])) j++;
      prev = /^(return|typeof|case|in|of|void|delete|throw|yield|await)$/.test(src.slice(i, j)) ? 'kw' : 'val';
      i = j; continue;
    }
    if (!/\s/.test(c)) prev = (c === ')' || c === ']') ? 'val' : c;
    i++;
  }
  return holes.length ? null : out.join('');
}

function _files(dir, out) {
  let ents = []; try { ents = fs.readdirSync(dir, { withFileTypes: true }); } catch (_) { return out; }
  for (const e of ents) {
    if (e.name.startsWith('.') || SKIP.has(e.name)) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) _files(p, out); else if (/\.(c|m)?js$/.test(e.name)) out.push(p);
  }
  return out;
}

/** outside(root) → [{ file, requires }] — every require that leaves this system's folder */
function outside(root) {
  const base = path.resolve(root);
  const out = [];
  for (const f of _files(base, [])) {
    let src = ''; try { src = fs.readFileSync(f, 'utf8'); } catch (_) { continue; }
    const code = codeOnly(src);
    for (const m of (code === null ? src : code).matchAll(REQ)) {
      const to = path.resolve(path.dirname(f), m[1] || m[2]);
      if (to !== base && !to.startsWith(base + path.sep)) out.push({ file: path.relative(base, f).split(path.sep).join('/'), requires: m[1] || m[2] });
    }
  }
  return out;
}

module.exports = { outside, codeOnly };

'use strict';
// lib/core.js — component [[slug]].core, capability [[slug]].core.observe: the system reporting on itself.
// Its commands are nodes (data/nodes/command/[[slug]].status.command, [[slug]].nodes.command); this file is only
// what they run.

function status(args, ctx) {
  return { ...ctx.heartbeat.snapshot(), shape: ctx.shape(), components: require('./commands.js').components(ctx).map(c => ({ id: c.id, status: c.status })) };
}

function nodes(args, ctx) {
  const type = args.type || 'component';
  return { type, nodes: ctx.index.list(type) };
}

module.exports = { status, nodes };

'use strict';
// lib/system.js — boot: config, schemas, the JAA store, the ledger and bus, the node index (and its first reindex),
// the listener and the heartbeat. server.js and cli.js both start here; neither builds any of this itself.
const path = require('path');
const config = require('../config.js');
const schemas = require('../schemas/index.js');
const taxonomy = require('../event-taxonomy.js');
const { JaaStore } = require('../jaa-store.js');
const { Ledger } = require('./ledger.js');
const { Bus } = require('./bus.js');
const { NodeIndex } = require('./node-index.js');
const { Listener } = require('./listener.js');
const { Heartbeat } = require('./heartbeat.js');
const boundary = require('./boundary.js');

const ROOT = path.resolve(__dirname, '..');

// The component shape: every component at least one capability, every capability at least one command, every
// command its events — each a node. A gap is a problem the heartbeat reports, not a crash.
function shape(ctx) {
  const out = [];
  for (const c of require('./commands.js').components(ctx)) {
    if (!(c.capabilities || []).length) out.push(`component ${c.id} has no capability`);
    for (const cap of c.capabilities || []) {
      if (!ctx.index.get('capability', cap)) out.push(`component ${c.id}: capability ${cap} has no node`);
      const cmds = ctx.index.list('command', { capability: cap });
      if (!cmds.length) out.push(`capability ${cap} has no command`);
      for (const cmd of cmds) if (!(cmd.events || []).length) out.push(`command ${cmd.id} has no events`);
    }
  }
  return out;
}

function boot({ root = ROOT, watch = false, beat = false, ledgerSession } = {}) {
  const cfg = config.load(root);
  const system = cfg.system;
  delete require.cache[require.resolve(path.join(root, 'registry-components.js'))];
  const registry = require(path.join(root, 'registry-components.js'));
  const store = new JaaStore(path.join(root, 'data', 'node-index'));
  const ledger = new Ledger(root, ledgerSession);
  const index = new NodeIndex({ root, store, schemas: schemas.create(path.join(root, 'schemas')) });
  const bus = new Bus(ledger, taxonomy.declared(index));
  const ctx = { root, system, config: cfg, registry, store, ledger, bus, index };
  ctx.listener = new Listener({ root, system, index, bus, pollMs: cfg.listener && cfg.listener.pollMs });
  ctx.listener.sync();
  // sovereign: the system holds only its own folder; a require that leaves it is a problem the heartbeat reports
  ctx.boundary = () => boundary.outside(root);
  ctx.heartbeat = new Heartbeat({ system, index, bus, intervalMs: cfg.heartbeatMs,
    checks: [() => ctx.boundary().map(o => `${o.file} requires ${o.requires}: outside this system (reach another system through its contract)`)] });
  ctx.shape = () => shape(ctx);
  if (watch) ctx.listener.start();
  if (beat) ctx.heartbeat.start();
  ctx.stop = () => { ctx.listener.stop(); ctx.heartbeat.stop(); };
  return ctx;
}

module.exports = { boot, shape, ROOT };

{
  "name": "[[slug]]",
