}

// registry-components.js — the spine. Every component connects only to this.
// Each id points at a node in data/nodes/; the node schemas are in schemas/. A new component is one entry here,
// its file in lib/, and its component, capability, command and event nodes — nothing else is rewired.
module.exports = {
  system: '[[slug]]',
  components: [
    {
      type: 'component',
      id: '[[slug]].core',
      uuid: '[[uuid8]]-core-0000-0000-000000000001',
      file: 'lib/core.js',
      intent: 'the system reporting on itself: its status and its nodes',
      version: '0.1.0',
      status: 'built',
      capabilities: ['[[slug]].core.observe'],
      hooks: ['[[slug]].core.http'],
      consumers: [],
      data: { dir: 'data/nodes', store: 'node', types: ['component', 'capability', 'command', 'event', 'route', 'hook', 'wire', 'bundle'] },
    },
    // the drawbridge: work moves to and from other systems as verified files (input/ → processing/ → done/ | failed/)
    {
      type: 'component',
      id: '[[slug]].handoff',
      uuid: '[[uuid8]]-hand-0000-0000-000000000101',
      file: 'lib/handoff.js',
      intent: 'work moves between systems as a file: verified by the registry and the handshake, then moved to the target\'s input/',
      version: '0.1.0',
      status: 'built',
      capabilities: ['[[slug]].handoff.move'],
      hooks: [],
      consumers: [],
      data: { dir: 'input, processing, done, failed, output', store: 'node', types: ['handoff'] },
    },
    // recursion: a module is a system — this skeleton again, one level down, from the system's own template
    {
      type: 'component',
      id: '[[slug]].modules',
      uuid: '[[uuid8]]-modu-0000-0000-000000000102',
      file: 'lib/modules.js',
      intent: 'a module is a system: the skeleton laid out again under modules/, from template/',
      version: '0.1.0',
      status: 'built',
      capabilities: ['[[slug]].modules.nest'],
      hooks: [],
      consumers: [],
      data: { dir: 'modules', store: 'node', types: ['module'] },
    },
    // ── the idea's components slot in below ──
  ],
  // the events a person should see, declared here so the UI reads them from the contract and keeps no list of its own
  // (James, 2026-10-17: "making the ui disposable, soveriegn"): [{ event: '[[slug]].x.done', level: 'ok'|'warn'|'err', text }]
  toasts: [],
};

'use strict';
// schemas/index.js — the system's own schemas, one file per node type (schema.<type>). The system owns these copies;
// a node type with no schema here is refused by the node index until one is added.
const fs = require('fs');
const path = require('path');

function loadAll(dir = __dirname) {
  const out = {};
  for (const f of fs.readdirSync(dir).filter(f => f.startsWith('schema.'))) {
    const doc = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'));
    if (doc.type !== 'schema') throw new Error(`schemas/${f}: type is "${doc.type}", expected "schema"`);
    out[doc.id] = doc.payload;
  }
  return out;
}

function create(dir = __dirname) {
  const all = loadAll(dir);
  return { get: (type) => all[type] || null, types: () => Object.keys(all).sort(), all };
}

module.exports = { create, loadAll };

'use strict';
// server.js — the API server. It serves the route nodes (data/nodes/route/): each one names a method, a path and the
// command it runs. A new route is a node dropped in its folder; this file does not change.
//   GET /health  the heartbeat snapshot · GET /contract  the contract with every route node · GET /nodes/:type[/:id]
//   POST /handoff  a handoff from another system lands in input/ · POST /handoff/receipt  how one this system sent went
const http = require('http');
const fs = require('fs');
const path = require('path');
const { boot } = require('./lib/system.js');
const commands = require('./lib/commands.js');
const handoff = require('./lib/handoff.js');

function _match(pattern, actual) {
  const p = pattern.split('/').filter(Boolean), a = actual.split('/').filter(Boolean);
  if (p.length !== a.length) return null;
  const params = {};
