// lib/ledger.js — the event ledger: every event, per session, timestamped, in data/ledger/<session>/events.jsonl.
const fs = require('fs');
const path = require('path');

function session() { return new Date().toISOString().replace(/[:.]/g, '-'); }

class Ledger {
